<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useClock} from '../../composables/useClock.js'
import {useListState} from '../../composables/useListState.js'
import MetricCard from '../../components/MetricCard.vue'
import ChartPanel from '../../components/ChartPanel.vue'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import NavIcon from '../../components/NavIcon.vue'
import {notify} from '../../composables/feedback.js'
import {columns,ordered,numberText,failureText,dateText} from '../alarms/supportUi.js'
const r=useIrrigation(),router=useRouter(),route=useRoute(),clock=useClock()
const groups=computed(()=>{const groups=new Map();for(const s of r.state.entities.CropSeason??[]){const key=s.plantingDate?.slice(0,4)+'|'+s.crop;if(!groups.has(key))groups.set(key,{key,label:s.crop+'种植季',ids:[],plantingDate:s.plantingDate});const item=groups.get(key);item.ids.push(s.seasonId);if(s.plantingDate<item.plantingDate)item.plantingDate=s.plantingDate}return [...groups.values()]})
const activeSeason=(r.state.entities.CropSeason??[]).find(s=>s.status==='ENABLED'),initialGroup=groups.value.find(g=>g.ids.includes(activeSeason?.seasonId)),state=useListState('water',{filters:{group:initialGroup?.key??'',start:clock.isReference?'2026-06-01':initialGroup?.plantingDate??clock.today.value,end:clock.isReference?'2026-07-28':clock.today.value,fieldId:route.query.fieldId??''}}),filters=ref({...state.filters}),report=ref(null),failure=ref(''),busy=ref(false),exportBusy=ref(false)
const queryFilters=computed(()=>({start:state.filters.start,end:state.filters.end,farmId:r.state.user?.farmId,...(state.filters.fieldId?{fieldId:state.filters.fieldId}:{}),...(state.filters.group?{seasonIds:groups.value.find(g=>g.key===state.filters.group)?.ids??[]}: {})}))
for(const key of ['fieldId','start','end'])if(route.query[key]){state.filters[key]=String(route.query[key]);filters.value[key]=String(route.query[key]);state.page=1}
let request=0
async function load(){const token=++request;busy.value=true;failure.value='';try{const result=await r.query('water',queryFilters.value);if(token===request)report.value=result}catch(e){if(token===request){report.value=null;failure.value=failureText(e)}}finally{if(token===request)busy.value=false}}
watch(()=>[r.state.revision,JSON.stringify(queryFilters.value)],()=>{if(r.state.user)load()},{immediate:true})
const rows=computed(()=>ordered([...(report.value?.rows??[])].sort((a,b)=>Date.parse(b.endedAt)-Date.parse(a.endedAt)||a.ledgerId.localeCompare(b.ledgerId)),state.sort)),visible=computed(()=>rows.value.slice((state.page-1)*15,state.page*15)),baseline=computed(()=>report.value?.baselineComparisons?.find(x=>x.comparable)??report.value?.baseline),jobs=computed(()=>[...(r.state.entities.ExportJob??[])].sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt))),job=computed(()=>jobs.value[0]),get=(kind,id)=>r.getIndex().byId[kind]?.get(id)
const cols=columns([['number','#',55],['ledgerId','账本编号',225],['fieldName','田块',195],['endedAt','日期',195],['volumeM3','水量 m³',180],['method','计量方式',175],['qualityStatus','状态']])
const fieldOrder=computed(()=>new Map((r.state.entities.Field??[]).map((field,index)=>[field.fieldId,index]))),chartFields=computed(()=>[...(report.value?.byField??[])].sort((a,b)=>(fieldOrder.value.get(a.fieldId)??Infinity)-(fieldOrder.value.get(b.fieldId)??Infinity)))
const chartOptions=computed(()=>({animation:false,grid:{left:112,right:88,top:6,bottom:4},xAxis:{type:'value',show:false},yAxis:{type:'category',inverse:true,data:chartFields.value.map(f=>f.fieldName),axisLine:{show:false},axisTick:{show:false},axisLabel:{fontSize:12,color:'#214236'}},series:[{type:'bar',data:chartFields.value.map(f=>({value:f.volumeM3,fieldId:f.fieldId,itemStyle:{color:state.filters.fieldId===f.fieldId?'#126c53':'#008d69'}})),barWidth:10,label:{show:true,position:'right',fontSize:12,color:'#173c31',formatter:p=>numberText(p.value)},itemStyle:{borderRadius:[0,1,1,0]}}],tooltip:{trigger:'axis',axisPointer:{type:'shadow'}}}))
function query(){state.filters={...filters.value};state.page=1}
function selectField(event){const id=event.data?.fieldId;if(!id)return;state.filters.fieldId=state.filters.fieldId===id?'':id;filters.value.fieldId=state.filters.fieldId;state.page=1}
async function createExport(snapshot){exportBusy.value=true;try{await r.commit('EXPORT_CREATE',{filters:snapshot??queryFilters.value},{clientRequestId:crypto.randomUUID()});notify('导出任务已创建')}catch(e){notify(failureText(e),'danger')}finally{exportBusy.value=false}}
function retryExport(){const f=job.value?.filterSnapshot??{};const start=f.start??f.startAt?.slice(0,10)??queryFilters.value.start,end=f.end??(f.endAt?new Date(Date.parse(f.endAt)-1).toISOString().slice(0,10):queryFilters.value.end);createExport({...f,start,end})}
async function cancelExport(){if(!job.value)return;try{await r.commit('EXPORT_CANCEL',{exportId:job.value.exportId},{expectedVersion:job.value.version,clientRequestId:crypto.randomUUID()});notify('导出任务已取消')}catch(e){notify(failureText(e),'danger')}}
async function download(){if(!job.value)return;try{const file=await r.query('exportFile',{exportId:job.value.exportId});const blob=new Blob([file.content],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=file.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('已下载用水明细')}catch(e){notify(failureText(e),'danger')}}
const fileAvailable=computed(()=>job.value?.status==='READY'&&!!job.value.csvContent&&Date.parse(job.value.expiresAt)>Date.now())
</script>
<template><div class="page-stack water-page"><form class="panel filters water-filters" @submit.prevent="query"><label class="filter-field">农场<select :value="r.state.user?.farmId"><option :value="r.state.user?.farmId">{{r.state.entities.Farm?.[0]?.name}}</option></select></label><label class="filter-field">种植季<select v-model="filters.group"><option value="">全部</option><option v-for="g in groups" :key="g.key" :value="g.key">{{g.label}}</option></select></label><label class="filter-field date-range">日期区间<span><input v-model="filters.start" type="date" aria-label="开始日期"/>—<input v-model="filters.end" type="date" aria-label="结束日期"/></span></label><button class="btn btn-primary" :disabled="busy">查询</button><button type="button" class="btn" :disabled="exportBusy||!report||!r.can('EXPORT_CREATE')" @click="createExport()">导出</button></form><p v-if="failure" role="alert" class="error-text">{{failure}} <button class="btn-link" @click="load">重试</button></p><template v-if="report"><div class="stat-grid water-metrics"><MetricCard label="区间总水量" :value="numberText(report.totalM3)" unit="m³" icon="water"/><MetricCard label="实测" :value="numberText(report.measuredM3)" unit="m³" icon="monitor"/><MetricCard label="分摊" :value="numberText(report.allocatedM3)" unit="m³" icon="network"/><MetricCard label="亩均用水" :value="numberText(report.perMuM3,2)" unit="m³/亩" icon="leaf"/></div><div class="water-charts"><section class="panel water-chart"><h2 class="panel-title">各田块用水量比较（m³）<button v-if="state.filters.fieldId" class="btn-link selected-field" @click="state.filters.fieldId='';filters.fieldId='';state.page=1">{{get('Field',state.filters.fieldId)?.name}} ×</button></h2><ChartPanel v-if="report.byField.length" :options="chartOptions" :height="257" @chart-click="selectField"/><p v-else class="empty-state">当前区间没有有效结算账本，请调整日期或种植季。</p></section><section class="panel baseline-panel"><h2 class="panel-title">基准区可比情况</h2><dl v-if="baseline" class="baseline-pairs"><dt>可比窗口日期</dt><dd>{{baseline.referenceStart===baseline.referenceEnd?baseline.referenceStart:baseline.referenceStart+' — '+baseline.referenceEnd}}</dd><dt>基准田块</dt><dd>{{get('Field',baseline.fieldId)?.name||'—'}}</dd><dt>面积</dt><dd>{{numberText(get('Field',baseline.fieldId)?.areaMu)}} 亩</dd><dt>参考水量</dt><dd>{{numberText(baseline.comparableReferenceM3)}} m³</dd><dt>实际水量</dt><dd>{{numberText(baseline.actualM3)}} m³</dd><dt>节水率</dt><dd class="saving">{{baseline.comparable?numberText(baseline.savingPercent,2)+'%':'不可比'}}</dd></dl><p v-else class="muted baseline-empty">当前区间无可比基准</p><div class="farm-saving"><span>全场节水率</span><strong v-if="report.farmSavingPercent!==null" class="saving">{{numberText(report.farmSavingPercent,2)}}%</strong><span v-else class="incomparable">不可计算：缺少全场同窗口可比基准</span></div></section></div><section class="panel water-table"><h2 class="panel-title">用水明细</h2><DataTable :columns="cols" :rows="visible" row-key="ledgerId" :selected-id="state.selectedId" :sort="state.sort" compact @update:sort="state.sort=$event" @row-click="state.selectedId=$event.ledgerId"><template #cell-number="{index}">{{(state.page-1)*15+index+1}}</template><template #cell-fieldName="{row,value}"><button class="btn-link" @click.stop="router.push('/fields/'+row.fieldId)">{{value}}</button></template><template #cell-endedAt="{value}">{{dateText(value).slice(0,10)}}</template><template #cell-volumeM3="{value}">{{numberText(value)}}</template><template #cell-method="{value}">{{{MEASURED:'实测',ALLOCATED:'分摊',ESTIMATED:'估算'}[value]||value}}</template><template #cell-qualityStatus>已结算</template></DataTable><Pagination v-model="state.page" :total="rows.length"/></section></template><p v-else-if="busy" class="empty-state">正在读取用水报表…</p><section v-if="job" class="panel export-card"><NavIcon name="audit" :size="34"/><div class="export-info"><strong>{{job.fileName||'用水明细.csv'}}</strong><small>任务编号：{{job.exportId}}</small><span v-if="['PENDING','PROCESSING','QUEUED','RUNNING'].includes(job.status)" class="export-progress"><progress :value="job.progress??0" max="100"/> {{job.progress??0}}%</span><span v-if="job.status==='FAILED'" class="error-text">{{job.errorMessage||job.failureReason||'导出失败，请重新导出'}}</span></div><StatusBadge :status="job.status" :text="job.status==='READY'?(fileAvailable?'可下载':'文件已过期或不可恢复'):undefined"/><button v-if="fileAvailable" class="btn btn-primary" @click="download"><NavIcon name="download"/>下载</button><button v-else-if="['PENDING','PROCESSING','QUEUED','RUNNING'].includes(job.status)" class="btn" :disabled="!r.can('EXPORT_CANCEL',job)" @click="cancelExport">取消导出</button><button v-else class="btn" :disabled="exportBusy||!r.can('EXPORT_CREATE')" @click="retryExport">重新导出</button></section><section v-else class="panel export-card muted">暂无导出任务，可按当前筛选导出用水明细。</section></div></template>
<style scoped>.water-page{gap:8px;margin-top:-5px}.water-filters{display:grid;grid-template-columns:260px 280px minmax(300px,1fr) 116px 116px;height:53px;padding:8px 18px;gap:16px;flex-wrap:nowrap}.water-filters .filter-field{flex:none;min-width:0;flex-direction:row;align-items:center;gap:12px;white-space:nowrap;font-size:13px}.water-filters select{width:215px;flex:none;height:34px}.water-filters .btn{height:34px;min-width:116px;padding:4px 14px}.water-filters .date-range{flex:1;min-width:0}.date-range>span{min-width:0;display:flex;align-items:center;border:1px solid #dce5e1;border-radius:5px;padding:0 7px}.date-range input{border:0;width:126px;padding:4px 2px;font-size:12px;min-height:30px}.water-metrics{gap:10px}.water-metrics :deep(.metric-card){height:82px;min-height:0;padding:12px 22px;gap:19px}.water-metrics :deep(.metric-icon){background:none;padding:0;min-width:32px}.water-metrics :deep(.metric-number){font-size:31px;color:#00846a}.water-metrics :deep(.metric-unit){font-size:14px;color:#607a71}.water-charts{display:grid;grid-template-columns:2.46fr 1fr;gap:8px;height:296px}.water-chart{padding:7px 15px}.water-page .panel-title{font-size:15px;margin:0 0 4px}.baseline-panel{padding:6px 8px}.baseline-panel .panel-title{padding:6px 13px;background:#ecf6f2;border-radius:5px}.baseline-pairs{display:grid;grid-template-columns:128px 1fr;font-size:14px;padding:7px 13px;margin:0;gap:8px 0}.baseline-pairs dt{color:#526e62}.baseline-pairs dd{margin:0;font-weight:600}.baseline-pairs .saving{font-size:25px;line-height:1.2;color:#00916c}.farm-saving{display:flex;align-items:center;gap:13px;padding-top:13px;margin:9px 13px 0;border-top:1px solid #e3eae6;font-size:13px;white-space:nowrap}.incomparable{background:#fff0d3;border-radius:5px;padding:7px 9px;color:#86631f;font-size:12px}.baseline-empty{height:180px;padding:15px}.water-table{padding:8px 13px}.water-table :deep(td){height:18px;font-size:12px;padding:0 19px;line-height:17px}.water-table :deep(th){height:22px;font-size:12px;padding-top:0;padding-bottom:0}.water-table :deep(.btn-link){min-height:0;height:17px;padding:0;font-size:12px;line-height:17px;color:#20342f}.water-table :deep(.pagination){min-height:35px;padding-top:8px;padding-bottom:0;font-size:12px}.water-table :deep(.page-button){width:27px;height:27px;min-width:27px}.export-card{min-height:80px;padding:13px 22px;display:flex;align-items:center;gap:23px}.export-info{display:flex;flex-direction:column;gap:5px;flex:1;font-size:15px}.export-info small{color:#71877d}.export-card .btn{min-width:119px;display:flex;align-items:center;justify-content:center;gap:12px;margin-left:10px}.export-progress{display:flex;gap:8px;align-items:center}.selected-field{float:right;font-size:12px}
</style>
